  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (0.00) and model shows upward bias.",
    "Correct for lagged overestimation: if model peaks 1-2 days after true price spike, reduce forecast by 1-2%.",
    "Apply mean reversion: if 3 consecutive forecasts are above true price, reduce next forecast by 1-3%.",
    "Reduce forecast overshoot after sharp spikes: if model exceeds true price by >5%, cap at 5% above true value.",
    "Increase forecast sensitivity to recent sentiment: if sentiment >0.25, adjust forecast upward by 0.5-1.5% for next 3 days."
  ]
